atts.custom_css:
selector,selector:hover{color:rgb(29, 19, 10) !important;}
selector{text-transform:uppercase !important;letter-spacing:2.6px !important;font-size:10px !important;font-weight:400 !important;padding:0px 22px 0px 22px !important;}
selector{align-self:center;width:auto;}
:where(selector){background-image:linear-gradient(rgba(255, 196, 116, 0.96), rgba(193, 124, 47, 0.92));line-height:15px;text-align:center;transition:transform 0.45s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.45s;}
